-- Back-dated Recent Assignment Activity, worded exactly like the automatic entries
insert into public.assignment_activity (description, actor_id, created_at)
select 'Client "' || ins.client_name || '" assigned to Associate "' || coalesce(nullif(p.full_name, ''), '(unnamed)') || '"',
       null::uuid, ins.assigned_at
from ins join public.profiles p on p.id = ins.assigned_associate_id
union all
select 'Inquiry from "' || ins.client_name || '" marked resolved', null::uuid, ins.resolved_at
from ins where ins.inquiry_status = 'resolved';

alter table public.inquiries enable trigger user;

commit;

-- Quick check: totals by outcome (compare with the counts at the top of this file)
select client_role, transaction_result, inquiry_status, count(*)
from public.inquiries group by 1, 2, 3 order by 1, 2, 3;
